import sys
from prefect import flow, task

@task
def my_task(x):
    if x % 4 == 0:
        raise ValueError(f"Failing on {x}")
    return x

@flow(name="test-flow")
def my_flow():
    futures = my_task.map(range(1, 21))
    # Let's print the type of futures and what's in there
    print("Futures type:", type(futures))
    print("Futures length:", len(futures))
    for i, f in enumerate(futures):
        print(f"Future {i+1}:", f)

if __name__ == "__main__":
    my_flow()

