import sys
from prefect import flow, task
from prefect.futures import resolve_futures_to_states

@task
def my_task(x):
    if x % 4 == 0:
        raise ValueError(f"Failing on {x}")
    return x

@flow(name="test-flow")
def my_flow():
    futures = my_task.map(range(1, 21))
    futures.wait()

    states = resolve_futures_to_states(futures)
    print("States type:", type(states))
    print("First state:", states[0])
    print("First state is_completed:", states[0].is_completed())

    failed_states = [s for s in states if s.is_failed()]
    print("Number of failed states:", len(failed_states))

    if failed_states:
        raise ValueError(f"{len(failed_states)} tasks failed!")

if __name__ == "__main__":
    try:
        my_flow()
    except Exception as e:
        print("Caught expected exception in main:", e)
